void topologicalSort(List<List<int>> graph) {
  int numVertices = graph.length;
  List<int> inDegree = List.filled(numVertices, 0);

  for (int i = 0; i < numVertices; i++) {
    for (int neighbor in graph[i]) {
      inDegree[neighbor]++;
    }
  }

  List<int> queue = [];
  for (int i = 0; i < numVertices; i++) {
    if (inDegree[i] == 0) {
      queue.add(i);
    }
  }

  List<int> topoOrder = [];
  int head = 0;
  while (head < queue.length) {
    int u = queue[head++];
    topoOrder.add(u);

    for (int neighbor in graph[u]) {
      inDegree[neighbor]--;
      if (inDegree[neighbor] == 0) {
        queue.add(neighbor);
      }
    }
  }

  if (topoOrder.length == numVertices) {
    print("Topological Sort:");
    print(topoOrder.join(" "));
  } else {
    print("Graph contains a cycle, topological sort not possible.");
  }
}

